        !empty(trim($_POST['field1'])) && !empty(trim($_POST['field2']))) {

        $field1 = trim($_POST['field1']);
        $field2 = trim($_POST['field2']);

        // Prepare an SQL statement to prevent SQL injection
        // Using 'submissions' table and columns 'field1', 'field2' as defined in setup_db.sql
        $stmt = $conn->prepare("INSERT INTO submissions (field1, field2) VALUES (?, ?)");

        if ($stmt) {
            // "ss" means the parameters are strings
            $stmt->bind_param("ss", $field1, $field2);

            if ($stmt->execute()) {
                $message = "Data submitted successfully!";
                $message_type = 'success';
