 * @param max_inner_elements_to_print Max elements to print from each inner array.
 *                                    Set to 0 or negative to print all.
 */
void print_rxdataF_contents(const RU_t *ru, const FRAME_PARMS_t *fp,
                            int max_elements_per_line, int max_inner_elements_to_print) {
    if (ru == NULL) {
        printf("Error: RU_t pointer is NULL.\n");
        return;
    }
