    printf("  NUMBER_RX_BUFFERS: %d\n", NUMBER_RX_BUFFERS);
    printf("  fp->symbols_per_slot: %d\n", fp->symbols_per_slot);
    printf("  fp->ofdm_symbol_size: %d\n", fp->ofdm_symbol_size);

