        printf("Error: One or more dimensions for inner array are zero or negative.\n");
        printf("  (NUMBER_RX_BUFFERS=%d, fp->symbols_per_slot=%d, fp->ofdm_symbol_size=%d)\n",
               NUMBER_RX_BUFFERS, fp->symbols_per_slot, fp->ofdm_symbol_size);
        return;
    }
    int inner_array_elements = NUMBER_RX_BUFFERS * fp->symbols_per_slot * fp->ofdm_symbol_size;
    printf("  Calculated inner array elements: %d\n\n", inner_array_elements);

    for (int i = 0; i < ru->nb_rx; i++) {
        printf("rxdataF[%d]:\n", i);
        if (ru->common.rxdataF[i] == NULL) {
            printf("  rxdataF[%d] is NULL (not allocated).\n", i);
            continue; // Move to the next outer array element
        }

        int elements_to_print = inner_array_elements;
        if (max_inner_elements_to_print > 0 && max_inner_elements_to_print < inner_array_elements) {
            elements_to_print = max_inner_elements_to_print;
            printf("  (Printing first %d of %d elements)\n", elements_to_print, inner_array_elements);
        }

        printf("  [");
        for (int j = 0; j < elements_to_print; j++) {
