                }
            }
            printf("%d", ru->common.rxdataF[i][j]);
        }
        printf("]\n");
        if (elements_to_print < inner_array_elements) {
            printf("  ... and %d more elements not shown.\n", inner_array_elements - elements_to_print);
        }
        printf("\n");
    }
    printf("--- End of rxdataF print ---\n");
