You can't make the model's `save()` method *magically* know about the "current user" from the HTTP request, because models are designed to be independent of the request-response cycle. They can be saved from management commands, background tasks, etc., where there's no "current user" in the web sense.

The standard and recommended way is to pass the user from the view (or form, or DRF serializer) to the model instance *before* calling `save()`.

Here are the common patterns:

**1. In a Django View (Manual Model Handling)**

If you're creating or updating model instances directly in your view:

```python
from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from .models import Features
from django.contrib.auth.models import User # Assuming you're using Django's default User

@login_required # Ensures request.user is an authenticated user
def create_feature_view(request):
    if request.method == 'POST':
        loaded_data_from_form = request.POST.get('loadeddata_field') # Get data from your form

        # When creating a new Feature
        feature = Features(
            loadeddata=loaded_data_from_form,
            user=request.user  # Assign the current user here
        )
        feature.save()
        return redirect('some_success_url') # Redirect after successful save

    return render(request, 'your_template_for_form.html')

@login_required
def update_feature_view(request, feature_id):
    try:
        feature = Features.objects.get(id=feature_id)
    except Features.DoesNotExist:
        # Handle not found error
        return redirect('some_error_url')

    # Optional: Check if the current user is the owner before allowing update
    if feature.user != request.user:
        # Handle permission denied
        return redirect('some_permission_denied_url')

    if request.method == 'POST':
        feature.loadeddata = request.POST.get('loadeddata_field')
        # feature.user is already set, no need to change it unless intended
        # If you were to change the user (less common for updates):
        # feature.user = request.user
        feature.save()
        return redirect('some_success_url')

    return render(request, 'your_template_for_update_form.html', {'feature': feature})
```

**2. Using Django Forms (ModelForm)**

This is a very common and clean way.

```python
# forms.py
from django import forms
from .models import Features

class FeatureForm(forms.ModelForm):
    class Meta:
        model = Features
        fields = ['loadeddata'] # Exclude 'user' as it will be set in the view

# views.py
from django.shortcuts import render, redirect
from django.contrib.auth.decorators import login_required
from .forms import FeatureForm
from .models import Features

@login_required
def create_feature_with_form(request):
    if request.method == 'POST':
        form = FeatureForm(request.POST)
        if form.is_valid():
            feature_instance = form.save(commit=False) # Don't save to DB yet
            feature_instance.user = request.user     # Assign the current user
            feature_instance.save()                  # Now save to DB
            # form.save_m2m() # If your form had m2m fields, call this after instance.save()
            return redirect('some_success_url')
    else:
        form = FeatureForm()
    return render(request, 'your_template_with_form.html', {'form': form})

@login_required
def update_feature_with_form(request, feature_id):
    try:
        feature_instance = Features.objects.get(id=feature_id)
    except Features.DoesNotExist:
        return redirect('some_error_url')

    if feature_instance.user != request.user: # Ownership check
        return redirect('some_permission_denied_url')

    if request.method == 'POST':
        form = FeatureForm(request.POST, instance=feature_instance)
        if form.is_valid():
            # User is already set on feature_instance, form.save() will preserve it
            # unless you explicitly try to change it in the form (which we excluded)
            form.save()
            return redirect('some_success_url')
    else:
        form = FeatureForm(instance=feature_instance)
    return render(request, 'your_template_with_form.html', {'form': form})
```

**3. Using Django REST framework (DRF) Serializers**

If you're building an API with DRF:

```python
# serializers.py
from rest_framework import serializers
from .models import Features

class FeatureSerializer(serializers.ModelSerializer):
    # User field can be read-only, as it's set by the view
    user = serializers.PrimaryKeyRelatedField(read_only=True)
    # Or, if you want to display user details:
    # user = serializers.StringRelatedField(read_only=True)

    class Meta:
        model = Features
        fields = ['id', 'user', 'created_at', 'updated_at', 'loadeddata']
        read_only_fields = ['user', 'created_at', 'updated_at'] # user is set in view

# views.py (DRF ViewSet)
from rest_framework import viewsets, permissions
from .models import Features
from .serializers import FeatureSerializer

class FeatureViewSet(viewsets.ModelViewSet):
    queryset = Features.objects.all()
    serializer_class = FeatureSerializer
    permission_classes = [permissions.IsAuthenticated] # Ensure user is logged in

    def perform_create(self, serializer):
        # When a new Feature is created, assign the current user
        serializer.save(user=self.request.user)

    def get_queryset(self):
        # Optionally, filter features to only show those owned by the current user
        return Features.objects.filter(user=self.request.user)

    # perform_update by default will just save the serializer.
    # The user is already on the instance and typically not changed during an update.
    # If you needed to change the user on update (rare), you'd override perform_update:
    # def perform_update(self, serializer):
    #     serializer.save(user=self.request.user) # Or some other logic
```

**Why not override `save()` in the model directly for this?**

While you *could* try a hacky solution involving thread-locals to pass the request object to the model's `save()` method, it's highly discouraged:
1.  **Breaks Separation of Concerns:** Models shouldn't know about HTTP requests.
2.  **Testing Difficulty:** Makes unit testing models harder as you'd need to mock request objects or thread-locals.
3.  **Unreliable:** Fails in non-request contexts (e.g., management commands, Celery tasks).
4.  **Less Explicit:** The logic becomes hidden and less obvious.

**Conclusion:**

The best practice is to explicitly set `instance.user = request.user` in your **view, form handling logic, or DRF serializer's `perform_create`/`perform_update` methods** before calling `instance.save()`. This keeps your code clean, testable, and follows Django's design principles.

Okay, here's a WordPress plugin that will attempt to clear the Nginx Helper cache when plugins or themes are activated, updated, or switched.

**Important Considerations:**

1.  **Nginx Helper Dependency:** This plugin *requires* the "Nginx Helper" plugin (by rtCamp) to be installed and active, as it relies on its functions to perform the cache purge.
2.  **Nginx Helper Version:** The Nginx Helper plugin has evolved. This code tries to use common methods (`Nginx_Purger::purge_all()` or `rt_nginx_helper_purge_all()`). If your Nginx Helper version uses a different mechanism, this plugin might need slight adjustments.
3.  **Server Configuration:** This plugin only triggers the *WordPress side* of the cache purge. Your Nginx server must be correctly configured with Nginx Helper (e.g., FastCGI Cache, Redis Cache, etc.) for the purge to actually take effect on the server.
4.  **Error Handling:** Basic checks are in place to see if Nginx Helper functions/classes exist.
5.  **Performance:** Clearing the entire cache on every minor plugin/theme change might be overkill for some sites and could temporarily increase server load. However, it ensures freshness.

---

**Plugin Code (save as `wp-nginx-auto-clear-cache.php` in your `wp-content/plugins/` directory):**

```php
<?php
/**
 * Plugin Name:       Nginx Helper Auto Cache Clearer
 * Plugin URI:        https://example.com/ (Replace with your URI)
 * Description:       Automatically clears Nginx Helper cache when plugins or themes are activated, updated, or switched.
 * Version:           1.1.0
 * Author:            Your Name
 * Author URI:        https://example.com/ (Replace with your URI)
 * License:           GPL v2 or later
 * License URI:       https://www.gnu.org/licenses/gpl-2.0.html
 * Text Domain:       nginx-auto-clear
 * Domain Path:       /languages
 */

// If this file is called directly, abort.
if ( ! defined( 'WPINC' ) ) {
    die;
}

define( 'NGINX_AUTO_CLEAR_VERSION', '1.1.0' );

/**
 * The core plugin class
 */
final class Nginx_Auto_Cache_Clearer {

    /**
     * Instance of this class.
     * @var object
     */
    private static $instance = null;

    /**
     * Singleton instance method.
     */
    public static function get_instance() {
        if ( null === self::$instance ) {
            self::$instance = new self();
        }
        return self::$instance;
    }

    /**
     * Constructor.
     */
    private function __construct() {
        add_action( 'plugins_loaded', array( $this, 'load_textdomain' ) );
        $this->add_hooks();
    }

    /**
     * Load plugin textdomain.
     */
    public function load_textdomain() {
        load_plugin_textdomain(
            'nginx-auto-clear',
            false,
            dirname( plugin_basename( __FILE__ ) ) . '/languages'
        );
    }

    /**
     * Add WordPress action hooks.
     */
    private function add_hooks() {
        // Plugin actions
        add_action( 'activated_plugin', array( $this, 'schedule_cache_clear' ), 10, 0 ); // After a plugin is activated
        add_action( 'deactivated_plugin', array( $this, 'schedule_cache_clear' ), 10, 0 ); // After a plugin is deactivated

        // Theme actions
        add_action( 'after_switch_theme', array( $this, 'schedule_cache_clear' ), 10, 0 ); // After a theme is switched

        // Covers plugin/theme installs and updates
        add_action( 'upgrader_process_complete', array( $this, 'handle_upgrader_action' ), 10, 2 );

        // Action to display admin notices
        add_action( 'admin_notices', array( $this, 'display_admin_notices' ) );
    }

    /**
     * Handles actions after upgrader (install/update for plugins/themes).
     *
     * @param WP_Upgrader $upgrader_object WP_Upgrader instance.
     * @param array       $options         Array of bulk item update data.
     */
    public function handle_upgrader_action( $upgrader_object, $options ) {
        if ( isset( $options['action'] ) && ( 'install' === $options['action'] || 'update' === $options['action'] ) ) {
            if ( isset( $options['type'] ) && ( 'plugin' === $options['type'] || 'theme' === $options['type'] ) ) {
                $this->schedule_cache_clear();
            }
        }
    }

    /**
     * Schedules a cache clear.
     * We use a shutdown action to ensure it runs after the triggering event is fully complete.
     */
    public function schedule_cache_clear() {
        if ( ! has_action( 'shutdown', array( $this, 'clear_nginx_helper_cache' ) ) ) {
            add_action( 'shutdown', array( $this, 'clear_nginx_helper_cache' ) );
        }
    }

    /**
     * Clears the Nginx Helper cache.
     */
    public function clear_nginx_helper_cache() {
        $cleared = false;
        $message_type = 'error'; // Default to error

        // Check for Nginx Helper and its purging mechanisms
        if ( class_exists( 'Nginx_Helper' ) ) {
            if ( class_exists( 'Nginx_Purger' ) && method_exists( 'Nginx_Purger', 'purge_all' ) ) {
                \Nginx_Purger::purge_all();
                $cleared = true;
                // error_log( 'Nginx Helper Cache: Cleared via Nginx_Purger::purge_all().' );
            } elseif ( function_exists( 'rt_nginx_helper_purge_all' ) ) {
                rt_nginx_helper_purge_all();
                $cleared = true;
                // error_log( 'Nginx Helper Cache: Cleared via rt_nginx_helper_purge_all().' );
            } elseif ( defined( 'RT_WP_NGINX_HELPER_PATH' ) && class_exists( 'Nginx_Helper_Admin' ) ) {
                // Fallback for potentially older versions or different structures
                // This might need an instance depending on the Nginx_Helper_Admin implementation
                // For safety, let's assume it might have a static method or a global instance.
                // If it requires `new Nginx_Helper_Admin()`, that could be problematic if not intended.
                // Typically, purge_all is static or called on an existing instance.
                // This part is speculative and depends on the specific Nginx Helper version.
                // For now, we'll assume if Nginx_Helper_Admin exists, it might have a static purge_all.
                if ( method_exists( 'Nginx_Helper_Admin', 'purge_all' ) ) {
                     // Check if it's static or needs an instance
                    $reflection = new ReflectionMethod('Nginx_Helper_Admin', 'purge_all');
                    if ($reflection->isStatic()) {
                        Nginx_Helper_Admin::purge_all();
                        $cleared = true;
                    } else {
                        // If it's not static, we might need to get an instance,
                        // but this is risky without knowing Nginx Helper's internals.
                        // For now, we'll log that it wasn't static.
                        // error_log( 'Nginx Helper Cache: Nginx_Helper_Admin::purge_all() exists but is not static. Cannot call.' );
                    }
                }
            }

            if ( $cleared ) {
                $message = __( 'Nginx Helper cache was automatically cleared due to a plugin/theme change.', 'nginx-auto-clear' );
                $message_type = 'success';
                set_transient( 'nginx_auto_clear_notice', array( 'message' => $message, 'type' => 'success' ), 60 );
            } else {
                $message = __( 'Nginx Helper Auto Clearer: Could not find a known Nginx Helper purge function. Cache might not be cleared.', 'nginx-auto-clear' );
                set_transient( 'nginx_auto_clear_notice', array( 'message' => $message, 'type' => 'warning' ), 60 );
                // error_log( $message );
            }

        } else {
            $message = __( 'Nginx Helper Auto Clearer: Nginx Helper plugin is not active. Cache cannot be cleared.', 'nginx-auto-clear' );
            set_transient( 'nginx_auto_clear_notice', array( 'message' => $message, 'type' => 'error' ), 60 );
            // error_log( $message );
        }
    }

    /**
     * Display admin notices from transients.
     */
    public function display_admin_notices() {
        if ( $notice_data = get_transient( 'nginx_auto_clear_notice' ) ) {
            $message = esc_html( $notice_data['message'] );
            $type    = esc_attr( $notice_data['type'] ); // 'success', 'warning', 'error', 'info'
            printf( '<div class="notice notice-%s is-dismissible"><p>%s</p></div>', $type, $message );
            delete_transient( 'nginx_auto_clear_notice' );
        }
    }
}

/**
 * Begins execution of the plugin.
 */
function nginx_auto_cache_clearer_run() {
    Nginx_Auto_Cache_Clearer::get_instance();
}
// Run the plugin
nginx_auto_cache_clearer_run();

```

---

**How to Use:**

1.  **Create the Plugin File:**
    *   Create a new folder in your `wp-content/plugins/` directory, for example, `nginx-helper-auto-clearer`.
    *   Inside this folder, create a PHP file named `wp-nginx-auto-clear-cache.php`.
    *   Copy and paste the code above into this file.
2.  **(Optional) Add Language Files:**
    *   If you want to translate the admin notices, create a `languages` folder inside your `nginx-helper-auto-clearer` plugin folder.
    *   Add your `.po` and `.mo` files there (e.g., `nginx-auto-clear-fr_FR.po`).
3.  **Activate the Plugin:**
    *   Go to your WordPress Admin > Plugins.
    *   Find "Nginx Helper Auto Cache Clearer" and click "Activate".
4.  **Test:**
    *   Make sure the "Nginx Helper" plugin by rtCamp is active and configured.
    *   Try activating a new (dummy) plugin, updating an existing plugin, or switching your theme.
    *   You should see an admin notice at the top of the WordPress admin area indicating whether the cache was cleared or if there was an issue (e.g., Nginx Helper not found).
    *   Check your Nginx cache (e.g., by looking at response headers or file system if using FastCGI file cache) to confirm it was actually purged.

**Explanation:**

*   **Plugin Header:** Standard WordPress plugin metadata.
*   **`Nginx_Auto_Cache_Clearer` Class:** Encapsulates the plugin's functionality. It's a singleton to ensure only one instance runs.
*   **`add_hooks()`:** This is where the magic happens. It hooks into:
    *   `activated_plugin`: Fires after a plugin is successfully activated.
    *   `deactivated_plugin`: Fires after a plugin is deactivated.
    *   `after_switch_theme`: Fires after you switch to a new theme.
    *   `upgrader_process_complete`: A versatile hook that fires after WordPress finishes installing or updating plugins, themes, or core. We check the `$options` to ensure it's a plugin or theme install/update.
*   **`schedule_cache_clear()`:** This function is called by the hooks. It uses `add_action( 'shutdown', ... )`. This is a good practice because it ensures the cache clearing happens at the very end of the PHP request, after the plugin activation/update/theme switch process is fully complete. It also prevents multiple clear calls in a single request if multiple hooks fire.
*   **`clear_nginx_helper_cache()`:**
    *   This is the core function that attempts the purge.
    *   It first checks if the `Nginx_Helper` class exists (meaning the plugin is likely active).
    *   Then, it tries to call `Nginx_Purger::purge_all()`, which is the modern way Nginx Helper handles full cache purges.
    *   As a fallback, it checks for the older `rt_nginx_helper_purge_all()` function.
    *   It also includes a speculative check for `Nginx_Helper_Admin::purge_all()` for very old versions, but this is less common for `purge_all`.
    *   It sets a transient to display an admin notice about the outcome.
*   **`display_admin_notices()`:** Shows the success/warning/error message to the admin using WordPress's standard admin notice system. Transients are used so the notice is shown once.
*   **`nginx_auto_cache_clearer_run()`:** Initializes the plugin.

This plugin provides a robust way to automate Nginx Helper cache clearing for common site modifications. Remember to test it in your specific environment.

instruction:
I have part of a Javascript function that I want to rewrite. Currently it searches every property Matches to find the minimum, and makes Player2 always be the first member. Instead, I want Player1 to be the lowest result sorting by Matches, and Player2 to be random each time the code is run.

function elo(data) {
  // Find the two players with the fewest matches.
  let minMatches = Number.MAX_SAFE_INTEGER;
  let Player1 = null;
  let Player2 = null;
  for (let player of data) {
    if (player.Matches < minMatches) {
      minMatches = player.Matches;
      Player1 = player;
      Player2 = data.find(p => p !== Player1);
    }
  }
}

output:
Okay, let's rewrite this function to meet your new requirements.

**Key Changes:**

1.  **Player1:** Instead of iterating and finding the minimum, we can sort the `data` array by `Matches` in ascending order and pick the first element. This ensures `Player1` is the one with the fewest matches. If there's a tie, the sort order will determine which one (usually the one that appeared first in the original array if the sort is stable, or it could be arbitrary for unstable sorts on objects without a secondary sort key).
2.  **Player2:** After selecting `Player1`, we'll create a new array containing all players *except* `Player1`. Then, we'll pick a random player from this new array.

Here's the updated Javascript function:

```javascript
function elo(data) {
  // Ensure there are at least two players to choose from
  if (!data || data.length < 2) {
    console.warn("ELO: Need at least two players to select from.");
    return { Player1: null, Player2: null }; // Or throw an error, depending on desired behavior
  }

  // 1. Determine Player1: Sort by Matches and pick the first one.
  // Create a shallow copy to avoid mutating the original data array.
  const sortedPlayers = [...data].sort((a, b) => a.Matches - b.Matches);
  const Player1 = sortedPlayers[0];

  // 2. Determine Player2: Randomly from the remaining players.
  // Filter out Player1 from the original data array to get potential candidates for Player2.
  // It's important to filter from `data` (or `sortedPlayers` if you are sure object references are maintained)
  // to ensure you are comparing the correct object instances.
  const otherPlayers = data.filter(player => player !== Player1);

  // If, for some reason (e.g., all players were identical objects, though unlikely with distinct player data),
  // otherPlayers is empty, we can't pick a Player2. This check is mostly a safeguard.
  // The initial data.length < 2 check should catch the primary scenario.
  if (otherPlayers.length === 0) {
    console.warn("ELO: Could not find a distinct second player.");
    return { Player1: Player1, Player2: null };
  }

  // Pick a random player from the 'otherPlayers' array
  const randomIndex = Math.floor(Math.random() * otherPlayers.length);
  const Player2 = otherPlayers[randomIndex];

  return { Player1, Player2 };
}

// --- Example Usage ---
const playerData = [
  { Name: "Alice", Matches: 10, Elo: 1500 },
  { Name: "Bob", Matches: 5, Elo: 1400 },
  { Name: "Charlie", Matches: 12, Elo: 1600 },
  { Name: "Diana", Matches: 5, Elo: 1450 }, // Bob and Diana have the same min matches
  { Name: "Edward", Matches: 20, Elo: 1300 }
];

console.log("Run 1:", elo(playerData));
console.log("Run 2:", elo(playerData));
console.log("Run 3:", elo(playerData));

const singlePlayerData = [{ Name: "Solo", Matches: 1, Elo: 1000 }];
console.log("Single Player:", elo(singlePlayerData));

const noPlayerData = [];
console.log("No Players:", elo(noPlayerData));

const twoPlayersData = [
  { Name: "P1", Matches: 2, Elo: 1000 },
  { Name: "P2", Matches: 10, Elo: 1000 }
];
console.log("Two Players:", elo(twoPlayersData));
```

**Explanation:**

1.  **Input Check:** The function first checks if `data` is valid and has at least two players. If not, it returns `null` for both players (or you could throw an error).
2.  **Sort for Player1:**
    *   `[...data]` creates a shallow copy of the `data` array. This is important so that the original `data` array passed to the function is not modified by the `sort()` method.
    *   `.sort((a, b) => a.Matches - b.Matches)` sorts the copied array. If `a.Matches - b.Matches` is negative, `a` comes before `b`. If positive, `b` comes before `a`. This results in an ascending sort by the `Matches` property.
    *   `const Player1 = sortedPlayers[0];` assigns the first player from the sorted list (the one with the fewest matches) to `Player1`.
3.  **Filter for Player2 Candidates:**
    *   `data.filter(player => player !== Player1)` creates a new array `otherPlayers` containing all players from the original `data` array *except* for the `Player1` object. We use strict inequality (`!==`) to compare object references.
4.  **Random Selection for Player2:**
    *   `Math.random()` generates a floating-point number between 0 (inclusive) and 1 (exclusive).
    *   `Math.random() * otherPlayers.length` scales this random number to the range of possible indices for `otherPlayers`.
    *   `Math.floor(...)` converts this to an integer index.
    *   `const Player2 = otherPlayers[randomIndex];` selects the player at that random index.
5.  **Return Value:** The function returns an object `{ Player1, Player2 }`.

Now, `Player1` will consistently be a player with the minimum number of matches, and `Player2` will be a different player chosen randomly from the rest.

Okay, here's a JavaScript function to compute the n-th Fibonacci number modulo p.

This function uses an iterative approach which is efficient for reasonably sized `n`. It takes advantage of the property `(a + b) mod p = ((a mod p) + (b mod p)) mod p`, applying the modulo at each step to keep the numbers manageable.

```javascript
/**
 * Computes the n-th Fibonacci number modulo p.
 * F(0) = 0, F(1) = 1
 * F(n) = F(n-1) + F(n-2) for n >= 2
 *
 * @param {number} n The index of the Fibonacci number (non-negative integer).
 * @param {number} p The modulus (positive integer).
 * @returns {number} The n-th Fibonacci number modulo p.
 */
function fibonacciModP(n, p) {
    if (typeof n !== 'number' || !Number.isInteger(n) || n < 0) {
        throw new Error("n must be a non-negative integer.");
    }
    if (typeof p !== 'number' || !Number.isInteger(p) || p <= 0) {
        throw new Error("p must be a positive integer.");
    }

    // Special case: if p is 1, any number modulo 1 is 0.
    if (p === 1) {
        return 0;
    }

    // Base cases for Fibonacci sequence
    if (n === 0) {
        return 0; // F(0) = 0. 0 mod p = 0.
    }
    if (n === 1) {
        return 1 % p; // F(1) = 1. 1 mod p = 1 (unless p=1, handled above).
    }

    // Iterative calculation with modulo at each step
    let prev = 0; // F(0) mod p
    let curr = 1; // F(1) mod p

    // We need to compute F(n). We already have F(0) and F(1).
    // The loop will run n-1 times to get from F(1) to F(n).
    // For example, if n=2: loop runs for i=2. next = (F(0)+F(1))%p = F(2)%p.
    // curr becomes F(2)%p.
    for (let i = 2; i <= n; i++) {
        let next = (prev + curr) % p;
        prev = curr;
        curr = next;
    }

    return curr;
}

// --- Examples ---
console.log("F(0) mod 5:", fibonacciModP(0, 5));   // Expected: 0
console.log("F(1) mod 5:", fibonacciModP(1, 5));   // Expected: 1
console.log("F(2) mod 5:", fibonacciModP(2, 5));   // Expected: (0+1)%5 = 1
console.log("F(3) mod 5:", fibonacciModP(3, 5));   // Expected: (1+1)%5 = 2
console.log("F(4) mod 5:", fibonacciModP(4, 5));   // Expected: (1+2)%5 = 3
console.log("F(5) mod 5:", fibonacciModP(5, 5));   // Expected: (2+3)%5 = 0
console.log("F(6) mod 5:", fibonacciModP(6, 5));   // Expected: (3+0)%5 = 3

console.log("F(10) mod 2:", fibonacciModP(10, 2)); // F(10) = 55. 55 mod 2 = 1
console.log("F(10) mod 3:", fibonacciModP(10, 3)); // F(10) = 55. 55 mod 3 = 1
console.log("F(20) mod 7:", fibonacciModP(20, 7)); // F(20) = 6765. 6765 mod 7 = 6765 % 7 = 5

// Example with p=1
console.log("F(5) mod 1:", fibonacciModP(5, 1));   // Expected: 0

// Example with large n (still manageable for this iterative approach)
console.log("F(100) mod 100:", fibonacciModP(100, 100)); // F(100) mod 100
// F(100) = 354224848179261915075.  ...075 mod 100 = 75.

// Example with a larger prime modulus
console.log("F(1000) mod 10007:", fibonacciModP(1000, 10007));

// Error handling examples (optional to run)
// try {
//     console.log(fibonacciModP(-1, 5));
// } catch (e) {
//     console.error(e.message);
// }
// try {
//     console.log(fibonacciModP(5, 0));
// } catch (e) {
//     console.error(e.message);
// }
// try {
//     console.log(fibonacciModP(5.5, 3));
// } catch (e) {
//     console.error(e.message);
// }
```

**Explanation:**

1.  **Input Validation:**
    *   Checks if `n` is a non-negative integer.
    *   Checks if `p` is a positive integer.
    *   Throws an error if inputs are invalid.

2.  **Special Case `p === 1`:**
    *   Any integer modulo 1 is 0. This is handled as a quick exit.

3.  **Base Cases `F(0)` and `F(1)`:**
    *   `F(0) = 0`. So, `F(0) mod p = 0`.
    *   `F(1) = 1`. So, `F(1) mod p = 1 % p`. (If `p > 1`, this is `1`. If `p=1`, it's `0`, but that's already handled by the `p===1` check).

4.  **Iterative Calculation:**
    *   `prev` stores `F(i-2) mod p`.
    *   `curr` stores `F(i-1) mod p`.
    *   The loop starts from `i = 2` (to calculate `F(2)`) up to `n`.
    *   In each iteration:
        *   `next = (prev + curr) % p`: This calculates `F(i) mod p` using the previously calculated `F(i-2) mod p` and `F(i-1) mod p`. The modulo operation `% p` is crucial here to keep the numbers from growing too large.
        *   `prev = curr`: Update `prev` to the old `curr`.
        *   `curr = next`: Update `curr` to the newly calculated `next`.
    *   After the loop finishes (when `i` has reached `n`), `curr` will hold `F(n) mod p`.

**Time and Space Complexity:**

*   **Time Complexity: O(n)** - The loop runs `n-1` times.
*   **Space Complexity: O(1)** - We only use a few variables (`prev`, `curr`, `next`, `i`) regardless of the size of `n`.

**For very large `n` (e.g., n > 10^9):**

If `n` can be extremely large, the O(n) approach might be too slow. In such cases, you would use:
1.  **Matrix Exponentiation:** Compute `[[1, 1], [1, 0]]^n mod p`, which can be done in O(log n) time.
2.  **Pisano Period:** The sequence of Fibonacci numbers modulo `p` is periodic. This period is called the Pisano period, `π(p)`. You can find `π(p)` (which is at most `p*p`), then compute `F(n % π(p)) mod p`. This is efficient if `p` is relatively small.
    *   Finding Pisano period: O(p^2) in the worst case.
    *   Calculating Fibonacci: O(π(p)), which is at most O(p^2).
    *   Overall: O(p^2).

The provided solution is generally the expected one unless constraints on `n` are extremely high.

Okay, here's a fairly comprehensive boilerplate for a Flask application with user authentication (registration, login, logout) using Flask-SQLAlchemy for the database, Flask-WTF for forms, and Flask-Login for session management.

This structure separates concerns into different files for better organization.

**Project Structure:**

```
flask_user_app/
├── app/
│   ├── __init__.py         # Initializes the Flask app and extensions
│   ├── models.py           # SQLAlchemy models (User)
│   ├── forms.py            # WTForms
│   ├── routes.py           # Application routes/views
│   ├── templates/
│   │   ├── base.html       # Base template
│   │   ├── login.html
│   │   ├── register.html
│   │   ├── index.html      # Homepage
│   │   └── account.html    # User account page (protected)
│   └── static/             # (Optional: for CSS, JS)
│       └── style.css
├── config.py               # Configuration settings
├── run.py                  # Script to run the application
└── requirements.txt        # Python dependencies
```

---

**1. `requirements.txt`:**

```txt
Flask
Flask-SQLAlchemy
Flask-Login
Flask-WTF
Werkzeug
email-validator # For WTForms email validation
python-dotenv   # Optional: for loading .env files
```
Install these: `pip install -r requirements.txt`

---

**2. `config.py`:**

```python
import os
from dotenv import load_dotenv

# Load environment variables from .env file (optional)
basedir = os.path.abspath(os.path.dirname(__file__))
load_dotenv(os.path.join(basedir, '.env'))

class Config:
    SECRET_KEY = os.environ.get('SECRET_KEY') or 'you-will-never-guess'
    SQLALCHEMY_DATABASE_URI = os.environ.get('DATABASE_URL') or \
        'sqlite:///' + os.path.join(basedir, 'app.db')
    SQLALCHEMY_TRACK_MODIFICATIONS = False
```
*(Optional: Create a `.env` file in the `flask_user_app` directory for `SECRET_KEY` if you use `python-dotenv`)*
```
SECRET_KEY='your_super_secret_random_string'
# DATABASE_URL='postgresql://user:password@host:port/database' # Example for PostgreSQL
```

---

**3. `app/__init__.py`:**

```python
from flask import Flask
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager
from config import Config

db = SQLAlchemy()
login_manager = LoginManager()
login_manager.login_view = 'auth.login' # The route for login
login_manager.login_message_category = 'info' # For flash messages

def create_app(config_class=Config):
    app = Flask(__name__)
    app.config.from_object(config_class)

    db.init_app(app)
    login_manager.init_app(app)

    # Import and register blueprints here
    # Example: from app.auth import bp as auth_bp
    # app.register_blueprint(auth_bp, url_prefix='/auth')

    # For simplicity, we'll define routes in routes.py and import them
    from app import routes, models # Import after app is created to avoid circular imports

    # Create database tables if they don't exist
    # This is okay for development, for production use Flask-Migrate
    with app.app_context():
        db.create_all()

    return app
