```python
from flask import render_template, flash, redirect, url_for, request
from flask_login import login_user, logout_user, current_user, login_required
from werkzeug.urls import url_parse # For redirecting after login
from app import db
from app.forms import LoginForm, RegistrationForm
from app.models import User

# This assumes you are using create_app factory, so 'app' is not directly available.
# Routes are typically defined within a Blueprint, but for simplicity here,
# we'll attach them to the app instance created by create_app.
# To do this properly, you would usually get the app instance from `current_app`.
# However, for this simple example, we can import `app` from `app` module if we structure __init__.py carefully.
# A better way for larger apps is to use Blueprints.

# Let's get the 'app' instance from the create_app factory.
# This is a bit of a workaround for not using Blueprints in this simple example.
# In a real app, these routes would be part of a Blueprint.
from flask import current_app as app

@app.route('/')
@app.route('/index')
def index():
    return render_template('index.html', title='Home')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated:
        return redirect(url_for('index'))
    form = LoginForm()
    if form.validate_on_submit():
        user = User.query.filter_by(email=form.email.data.lower()).first()
        if user is None or not user.check_password(form.password.data):
            flash('Invalid email or password', 'danger')
            return redirect(url_for('login'))
        login_user(user, remember=form.remember_me.data)
        next_page = request.args.get('next')
        if not next_page or url_parse(next_page).netloc != '': # Security: ensure next_page is internal
            next_page = url_for('index')
        flash(f'Welcome back, {user.username}!', 'success')
        return redirect(next_page)
    return render_template('login.html', title='Sign In', form=form)

@app.route('/logout')
@login_required # Ensure user is logged in to logout
def logout():
    logout_user()
    flash('You have been logged out.', 'info')
    return redirect(url_for('index'))

@app.route('/register', methods=['GET', 'POST'])
def register():
    if current_user.is_authenticated:
        return redirect(url_for('index'))
    form = RegistrationForm()
    if form.validate_on_submit():
        user = User(username=form.username.data.strip(), email=form.email.data.lower().strip())
        user.set_password(form.password.data)
        db.session.add(user)
        db.session.commit()
        flash('Congratulations, you are now a registered user! Please log in.', 'success')
        return redirect(url_for('login'))
    return render_template('register.html', title='Register', form=form)

@app.route('/account')
@login_required # This route requires the user to be logged in
def account():
    return render_template('account.html', title='Account')

