**2. `MyVpnService.kt`**

This is the core of the VPN.

```kotlin
package com.example.mylocalvpn // Replace with your package name

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Intent
import android.net.VpnService
import android.os.Build
import android.os.ParcelFileDescriptor
import android.util.Log
import androidx.core.app.NotificationCompat
import java.io.FileInputStream
import java.io.FileOutputStream
import java.net.Inet4Address
import java.net.InetAddress
import java.nio.ByteBuffer

class MyVpnService : VpnService() {

    private val TAG = "MyVpnService"
    private val VPN_CHANNEL_ID = "MyVpnServiceChannel"
    private val VPN_NOTIFICATION_ID = 1

    private var vpnInterface: ParcelFileDescriptor? = null
    private var vpnThread: Thread? = null

    // --- Configuration ---
    private val VPN_ADDRESS = "10.0.0.2" // Internal VPN address
    private val VPN_ROUTE = "0.0.0.0"    // Intercept all traffic
    private val VPN_DNS = "8.8.8.8"      // Example DNS

    // --- Filtering ---
    // Add IPs you want to block here (as strings)
    private val blockedDestinationIPs = setOf(
        "1.1.1.1", // Example: Cloudflare DNS (will be blocked if uncommented)
        "172.217.160.142" // Example: google.com (will be blocked if uncommented)
    )

    companion object {
        const val ACTION_CONNECT = "com.example.mylocalvpn.CONNECT"
        const val ACTION_DISCONNECT = "com.example.mylocalvpn.DISCONNECT"
    }

    override fun onCreate() {
        super.onCreate()
        Log.d(TAG, "onCreate")
        createNotificationChannel()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Log.d(TAG, "onStartCommand action: ${intent?.action}")
        when (intent?.action) {
            ACTION_CONNECT -> {
                startVpn()
                return START_STICKY
            }
            ACTION_DISCONNECT -> {
                stopVpn()
                return START_NOT_STICKY
            }
        }
        return START_NOT_STICKY
    }

    private fun startVpn() {
        if (vpnThread?.isAlive == true) {
            Log.d(TAG, "VPN already running")
            return
        }

        Log.d(TAG, "Starting VPN...")
        showNotification("VPN Connected", "Tap to disconnect")

        vpnThread = Thread {
            try {
                val builder = Builder()
                builder.setMtu(1500)
                builder.addAddress(VPN_ADDRESS, 24)
                builder.addRoute(VPN_ROUTE, 0)
                builder.addDnsServer(VPN_DNS)
                builder.setSession(getString(R.string.app_name)) // Use app name for session

                // Important: Protect sockets used by the VPN service itself from looping back
                // For this simple example, we don't create outgoing sockets from the service,
                // but if you did (e.g., to resolve DNS or connect to a control server),
                // you would need to call protect() on them.

                vpnInterface = builder.establish()
                if (vpnInterface == null) {
                    Log.e(TAG, "Failed to establish VPN interface.")
                    stopVpn() // Clean up notification if setup fails
                    return@Thread
                }
                Log.d(TAG, "VPN interface established.")

                val vpnInput = FileInputStream(vpnInterface!!.fileDescriptor)
                val vpnOutput = FileOutputStream(vpnInterface!!.fileDescriptor)

                val packet = ByteBuffer.allocate(32767) // Max packet size

                while (vpnThread?.isInterrupted == false) {
                    val length = vpnInput.read(packet.array())
                    if (length > 0) {
                        packet.limit(length) // Set limit to actual data read

                        // --- Packet Parsing and Filtering (IPv4) ---
                        if (isIPv4Packet(packet)) {
                            val destIp = getDestinationIp(packet)
                            val destIpString = destIp?.hostAddress ?: "Unknown"
                            Log.d(TAG, "Packet read (len: $length): Dest IP: $destIpString")

                            if (blockedDestinationIPs.contains(destIpString)) {
                                Log.w(TAG, "BLOCKING packet to: $destIpString")
                                // Drop the packet by not writing it to vpnOutput
                            } else {
                                Log.d(TAG, "ALLOWING packet to: $destIpString")
                                vpnOutput.write(packet.array(), 0, length)
                            }
                        } else {
                            // Not an IPv4 packet (or malformed), just pass it through for simplicity
                            // A more robust solution would handle IPv6 or drop unknown packet types
                            Log.d(TAG, "Non-IPv4 packet or parse error, allowing (len: $length)")
                            vpnOutput.write(packet.array(), 0, length)
                        }
                        packet.clear()
                    } else {
                        Thread.sleep(10) // Avoid busy-looping if no data
                    }
                }
            } catch (e: InterruptedException) {
                Log.d(TAG, "VPN thread interrupted.")
            } catch (e: Exception) {
                Log.e(TAG, "VPN run error", e)
            } finally {
                Log.d(TAG, "VPN thread stopping...")
                closeVpnInterface()
            }
        }
        vpnThread?.start()
    }

    private fun isIPv4Packet(packet: ByteBuffer): Boolean {
        if (packet.remaining() < 20) return false // Minimum IPv4 header size
        // Check IP version (first 4 bits of the first byte)
        val version = (packet.get(0).toInt() and 0xF0) ushr 4
        return version == 4
    }

    private fun getDestinationIp(packet: ByteBuffer): InetAddress? {
        // IPv4 header: Destination IP address is at offset 16 (4 bytes)
        // Ensure packet has enough data for IP header (at least 20 bytes for IPv4)
        if (packet.limit() < 20) return null
        try {
            val ipBytes = ByteArray(4)
            packet.position(16) // Move to destination IP offset
            packet.get(ipBytes)
            return InetAddress.getByAddress(ipBytes) as? Inet4Address
        } catch (e: Exception) {
            Log.e(TAG, "Error parsing destination IP", e)
            return null
        } finally {
            packet.position(0) // Reset position for next read/write
        }
    }

    private fun stopVpn() {
        Log.d(TAG, "Stopping VPN...")
        vpnThread?.interrupt() // Signal the thread to stop
        try {
            vpnThread?.join(1000) // Wait for the thread to finish
        } catch (e: InterruptedException) {
            Log.e(TAG, "Interrupted while waiting for VPN thread to join", e)
        }
        vpnThread = null
        closeVpnInterface()
        stopForeground(true)
        stopSelf()
        Log.d(TAG, "VPN stopped.")
    }

    private fun closeVpnInterface() {
        try {
            vpnInterface?.close()
            vpnInterface = null
            Log.d(TAG, "VPN interface closed.")
        } catch (e: Exception) {
            Log.e(TAG, "Error closing VPN interface", e)
        }
    }

    private fun createNotificationChannel() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            val name = "My VPN Service"
            val descriptionText = "Notification channel for My VPN Service"
            val importance = NotificationManager.IMPORTANCE_DEFAULT
            val channel = NotificationChannel(VPN_CHANNEL_ID, name, importance).apply {
                description = descriptionText
            }
            val notificationManager: NotificationManager =
                getSystemService(NOTIFICATION_SERVICE) as NotificationManager
            notificationManager.createNotificationChannel(channel)
        }
    }

    private fun showNotification(title: String, message: String) {
        val disconnectIntent = Intent(this, MyVpnService::class.java).apply {
            action = ACTION_DISCONNECT
        }
        val disconnectPendingIntent: PendingIntent =
            PendingIntent.getService(this, 0, disconnectIntent, PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT)

        val notification = NotificationCompat.Builder(this, VPN_CHANNEL_ID)
            .setContentTitle(title)
            .setContentText(message)
            .setSmallIcon(R.mipmap.ic_launcher) // Replace with your app's icon
            .addAction(R.mipmap.ic_launcher_round, "Disconnect", disconnectPendingIntent) // Action button
            .setOngoing(true) // Makes the notification non-dismissable by swiping
            .build()

        startForeground(VPN_NOTIFICATION_ID, notification)
    }


    override fun onDestroy() {
        Log.d(TAG, "onDestroy")
        stopVpn() // Ensure cleanup
        super.onDestroy()
    }

    // onRevoke is called if the user revokes VPN permission while it's running
    override fun onRevoke() {
        Log.w(TAG, "VPN permission revoked by user or system.")
        stopVpn()
        super.onRevoke()
    }
}
```

