```kotlin
package com.example.mylocalvpn // Replace with your package name

import android.app.Activity
import android.content.Intent
import android.net.VpnService
import android.os.Bundle
import android.util.Log
import android.widget.Button
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity

class MainActivity : AppCompatActivity() {

    private val TAG = "MainActivity"
    private lateinit var vpnButton: Button
    private var isVpnRunning = false // Simple state tracking

    // Activity result launcher for VPN permission
    private val vpnPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
            if (result.resultCode == Activity.RESULT_OK) {
                Log.d(TAG, "VPN permission granted. Starting VPN.")
                startVpnService()
            } else {
                Log.e(TAG, "VPN permission denied.")
                // Handle permission denial (e.g., show a message to the user)
                updateButtonState()
            }
        }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main) // Make sure you have this layout

        vpnButton = findViewById(R.id.vpnButton)
        vpnButton.setOnClickListener {
            if (isVpnRunning) {
                stopVpnService()
            } else {
                requestVpnPermission()
            }
        }
        // You might want to check the actual service state on resume for more robustness
        // For simplicity, this example relies on the local isVpnRunning flag
        updateButtonState()
    }

    private fun requestVpnPermission() {
        val prepareVpnIntent: Intent? = VpnService.prepare(this)
        if (prepareVpnIntent != null) {
            Log.d(TAG, "VPN permission needed. Launching dialog.")
            vpnPermissionLauncher.launch(prepareVpnIntent)
        } else {
            Log.d(TAG, "VPN permission already granted. Starting VPN.")
            startVpnService() // Permission already granted
        }
    }

    private fun startVpnService() {
        val intent = Intent(this, MyVpnService::class.java).apply {
            action = MyVpnService.ACTION_CONNECT
        }
        startService(intent)
        isVpnRunning = true
        updateButtonState()
    }

    private fun stopVpnService() {
        val intent = Intent(this, MyVpnService::class.java).apply {
            action = MyVpnService.ACTION_DISCONNECT
        }
        startService(intent) // Send disconnect action to service
        isVpnRunning = false
        updateButtonState()
    }

    private fun updateButtonState() {
        if (isVpnRunning) {
            vpnButton.text = "Stop VPN"
        } else {
            vpnButton.text = "Start VPN"
        }
    }

    // Optional: Update button state based on a more reliable service check
    // e.g., by using a BroadcastReceiver or checking a static flag in the service
    override fun onResume() {
        super.onResume()
        // A more robust way to check if VPN is running would be needed for production
        // For this example, we'll assume our `isVpnRunning` flag is mostly correct
        // or you could query the service if it's active.
        // updateButtonState() // Potentially refresh here
    }
}
