};
```

Now, configure the `Favorite` model (`app/Models/Favorite.php`):

```php
<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Model;

class Favorite extends Model
{
    use HasFactory;

    protected $fillable = [
        'user_id',
        'name',
    ];

    /**
     * Get the user that owns the favorite.
     */
    public function user()
    {
        return $this->belongsTo(User::class);
    }
}
```
Don't forget to run `php artisan migrate`.

**2. Implement `FavoritesManager`:**

This class will contain the core logic. We can inject the `Request` to handle session data and `Auth` to check for logged-in users.

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;
use Illuminate\Http\Request; // Added
use Illuminate\Support\Facades\Auth; // Added
use Illuminate\Support\Collection; // Added

class FavoritesManager
{
    protected const SESSION_KEY = 'guest_favorites';

    protected ?User $user;
    protected Request $request;

    public function __construct(Request $request)
    {
        $this->request = $request;
        $this->user = Auth::user(); // Get the authenticated user, if any
    }

    /**
     * Add a name to the favorites list.
     *
     * @param string $name
     * @return bool True if added, false if already exists (or on failure for DB)
     */
    public function add(string $name): bool
    {
        if ($this->user) {
            // Logged-in user: save to database
            // Use firstOrCreate to prevent duplicates and handle existing entries gracefully
            $favorite = Favorite::firstOrCreate(
                ['user_id' => $this->user->id, 'name' => $name]
            );
            return $favorite->wasRecentlyCreated || $favorite->exists; // True if new or already there
        } else {
            // Guest user: save to session
            $favorites = $this->getSessionFavorites();
            if (!$favorites->contains($name)) {
                $favorites->push($name);
                $this->request->session()->put(self::SESSION_KEY, $favorites->all());
                return true;
            }
            return false; // Already in session
        }
    }

    /**
     * Remove a name from the favorites list.
     *
     * @param string $name
     * @return bool True if removed, false if not found
     */
    public function remove(string $name): bool
    {
        if ($this->user) {
            // Logged-in user: remove from database
            $deletedCount = Favorite::where('user_id', $this->user->id)
                                   ->where('name', $name)
                                   ->delete();
            return $deletedCount > 0;
        } else {
            // Guest user: remove from session
            $favorites = $this->getSessionFavorites();
            if ($favorites->contains($name)) {
                $updatedFavorites = $favorites->reject(fn($favName) => $favName === $name);
                $this->request->session()->put(self::SESSION_KEY, $updatedFavorites->values()->all());
                return true;
            }
            return false; // Not found in session
        }
    }

    /**
     * Get all favorite names.
     *
     * @return Collection
     */
    public function getAll(): Collection
    {
        if ($this->user) {
            // Logged-in user: fetch from database
            return Favorite::where('user_id', $this->user->id)->pluck('name');
        } else {
            // Guest user: fetch from session
            return $this->getSessionFavorites();
        }
    }

    /**
     * Check if a specific name is in favorites.
     *
     * @param string $name
     * @return bool
     */
    public function has(string $name): bool
    {
        if ($this->user) {
            return Favorite::where('user_id', $this->user->id)->where('name', $name)->exists();
        } else {
            return $this->getSessionFavorites()->contains($name);
        }
    }

    /**
     * Helper to get guest favorites from session, ensuring it's a Collection.
     *
     * @return Collection
     */
    protected function getSessionFavorites(): Collection
    {
        return collect($this->request->session()->get(self::SESSION_KEY, []));
    }

    /**
     * Clear all guest favorites (e.g., on login/logout).
     */
    public function clearGuestFavorites(): void
    {
        $this->request->session()->forget(self::SESSION_KEY);
    }

    /**
     * Merge guest favorites into the authenticated user's DB favorites.
     * Typically called after a guest logs in.
     *
     * @param User $user The user who just logged in.
     */
    public function mergeGuestFavoritesToUser(User $user): void
    {
        $guestFavorites = $this->getSessionFavorites();
        if ($guestFavorites->isNotEmpty()) {
            $now = now();
            $dataToInsert = $guestFavorites->map(function ($name) use ($user, $now) {
                return [
                    'user_id' => $user->id,
                    'name' => $name,
                    'created_at' => $now,
                    'updated_at' => $now,
                ];
            })->all();

            // Use insertOrIgnore to avoid errors if a favorite already exists for the user
            // This is more efficient than firstOrCreate in a loop for many items.
            Favorite::insertOrIgnore($dataToInsert);

            $this->clearGuestFavorites();
        }
    }
}
```

**3. Implement `FavoritesController`:**

This controller will use the `FavoritesManager`.

```php
<?php

namespace App\Http\Controllers;

use App\Favorites\FavoritesManager;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Auth; // Keep for potential direct use, though manager handles it
use Illuminate\Validation\Rule; // For validation if needed

class FavoritesController extends Controller
{
    protected FavoritesManager $favoritesManager;

    // Inject FavoritesManager. Laravel's service container will automatically
    // resolve its dependencies (like Request).
    public function __construct(FavoritesManager $favoritesManager)
    {
        $this->favoritesManager = $favoritesManager;
    }

    /**
     * Display a listing of the user's/guest's favorite names.
     *
     * @return \Illuminate\Http\JsonResponse
     */
    public function index()
    {
        $favorites = $this->favoritesManager->getAll();
        return response()->json($favorites);
    }

    /**
     * Store a newly created favorite name in storage.
     *
     * @param  \Illuminate\Http\Request  $request
     * @return \Illuminate\Http\JsonResponse
     */
    public function store(Request $request)
    {
        $validated = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $name = $validated['name'];

        if ($this->favoritesManager->add($name)) {
            // Optionally, return the updated list or just a success message
            return response()->json([
                'message' => 'Favorite added successfully.',
                'name' => $name, // Echo back the name
                // 'favorites' => $this->favoritesManager->getAll() // Or return all
            ], 201); // 201 Created (or 200 OK if it's more of an update/idempotent)
        }

        return response()->json([
            'message' => 'Favorite already exists or could not be added.',
            'name' => $name,
        ], 409); // 409 Conflict (or 200 if already exists is fine)
    }

    /**
     * Remove the specified favorite name from storage.
     *
     * @param  string  $name The name to remove (passed as a route parameter)
     * @return \Illuminate\Http\JsonResponse
     */
    public function destroy(string $name) // Laravel will automatically URL-decode $name
    {
        // No specific validation needed for $name here as it's from the URL,
        // but ensure it's treated as a string.
        // The $name parameter will be URL-decoded automatically by Laravel.

        if ($this->favoritesManager->remove($name)) {
            return response()->json([
                'message' => 'Favorite removed successfully.',
                'name' => $name
            ]);
        }

        return response()->json([
            'message' => 'Favorite not found or could not be removed.',
            'name' => $name
        ], 404); // 404 Not Found
    }

    /**
     * Check if a specific name is favorited.
     *
     * @param Request $request
     * @return \Illuminate\Http\JsonResponse
     */
    public function check(Request $request)
    {
        $validated = $request->validate([
            'name' => 'required|string|max:255',
        ]);

        $isFavorite = $this->favoritesManager->has($validated['name']);

        return response()->json([
            'name' => $validated['name'],
            'isFavorite' => $isFavorite,
        ]);
    }
}
```

**4. Define Routes (e.g., in `routes/web.php` or `routes/api.php`):**

Since this is for an Inertia app, these routes are typically in `web.php` and protected by web middleware (which handles session, CSRF, etc.).

```php
<?php

use App\Http\Controllers\FavoritesController;
use Illuminate\Support\Facades\Route;

// ... other routes

Route::prefix('favorites')->name('favorites.')->group(function () {
    Route::get('/', [FavoritesController::class, 'index'])->name('index');
    Route::post('/', [FavoritesController::class, 'store'])->name('store');
    Route::delete('/{name}', [FavoritesController::class, 'destroy'])->name('destroy'); // Route model binding not used here, simple string
    Route::get('/check', [FavoritesController::class, 'check'])->name('check'); // To check a specific name status
});

// You might also want a route to trigger merging guest favorites on login.
// This would typically be called from your LoginController after successful authentication.
// Example (conceptual, adapt to your login flow):
// In your LoginController's authenticated() method:
/*
use App\Favorites\FavoritesManager;
// ...
protected function authenticated(Request $request, $user)
{
    $favoritesManager = app(FavoritesManager::class); // Resolve from container
    $favoritesManager->mergeGuestFavoritesToUser($user);

    // ... redirect to intended or dashboard
}
*/
```
**Important notes on `destroy` route:**
When you pass a name like "My Business Name" in the URL, it will be URL-encoded (e.g., "My%20Business%20Name"). Laravel automatically decodes this when it's bound to a controller method parameter. So, in your `destroy(string $name)` method, `$name` will correctly be "My Business Name". Your frontend (Vue) will need to make sure it correctly URL-encodes the name when constructing the DELETE request URL. `encodeURIComponent()` in JavaScript is your friend here.

**5. (Optional but Recommended) Service Provider:**

While Laravel can auto-resolve `FavoritesManager` and its `Request` dependency, you could register it explicitly in a service provider if you want more control or if the construction logic becomes more complex. For this setup, it's not strictly necessary.

```php
// app/Providers/AppServiceProvider.php or a dedicated FavoritesServiceProvider.php

// public function register(): void
