        // If X fails, you might want to try to revert RO if possible, or just free
        set_memory_rw(shellcode_addr, num_pages_shellcode); // Try to make it RW again for freeing
        vfree(executable_mem);
        return ret;
    }
    pr_info("Memory set to X.\n");

    // Now you can call it (carefully!)
    pr_info("Executing shellcode...\n");
    ((shellcode_func_t)executable_mem)();
    pr_info("Shellcode executed.\n");

    return 0;
}

static void __exit my_module_exit(void) {
