            websocket.send(error_msg)
        except ConnectionClosed:
            print("Client disconnected before unexpected error could be sent.")
        finally:
            # Ensure the websocket is closed in case of an unhandled exception path
            try:
                websocket.close(reason=1011, message="Internal server error") # 1011: Internal Error
            except: # pylint: disable=bare-except
                pass # Already closed or cannot be closed

# Example of how to run this (if this is your main file)
if __name__ == '__main__':
    # You would typically run this with a WSGI server like gunicorn or uwsgi
    # For development:
    # gunicorn -k geventwebsocket.gunicorn.workers.GeventWebSocketWorker -w 1 myapp:app
    # or using Flask's built-in server (less ideal for WebSockets in production)
    print("Starting Flask development server. Use a proper WSGI server for production.")
    app.run(debug=True, port=5000)
```

