```javascript
document.addEventListener('DOMContentLoaded', () => {
    const canvas = document.getElementById('spriteCanvas');
    const ctx = canvas.getContext('2d');

    const gridWidthInput = document.getElementById('gridWidth');
    const gridHeightInput = document.getElementById('gridHeight');
    const pixelSizeInput = document.getElementById('pixelSize');
    const colorPicker = document.getElementById('colorPicker');
    const pencilToolButton = document.getElementById('pencilTool');
    const eraserToolButton = document.getElementById('eraserTool');
    const clearCanvasButton = document.getElementById('clearCanvas');
    const exportSpriteButton = document.getElementById('exportSprite');

    let gridWidth = parseInt(gridWidthInput.value);
    let gridHeight = parseInt(gridHeightInput.value);
    let pixelSize = parseInt(pixelSizeInput.value);
    let selectedColor = colorPicker.value;
    let currentTool = 'pencil'; // 'pencil' or 'eraser'
    const transparentColor = 'rgba(0,0,0,0)'; // For eraser and empty cells

    // Sprite data: 2D array storing color of each pixel
    let spriteData = [];

    function initializeSpriteData() {
        spriteData = [];
        for (let y = 0; y < gridHeight; y++) {
            const row = [];
            for (let x = 0; x < gridWidth; x++) {
                row.push(transparentColor); // Initialize with transparent
            }
            spriteData.push(row);
        }
    }

    function resizeCanvas() {
        canvas.width = gridWidth * pixelSize;
        canvas.height = gridHeight * pixelSize;
        // Important for sharp pixels when scaling
        ctx.imageSmoothingEnabled = false;
        drawGrid();
    }

    function drawGrid() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        for (let y = 0; y < gridHeight; y++) {
            for (let x = 0; x < gridWidth; x++) {
                ctx.fillStyle = spriteData[y][x];
                ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
            }
        }

        // Optional: Draw grid lines for better visibility if pixelSize is large
        if (pixelSize > 4) {
            ctx.strokeStyle = '#ddd';
            ctx.lineWidth = 0.5;
            for (let x = 0; x <= gridWidth; x++) {
                ctx.beginPath();
                ctx.moveTo(x * pixelSize, 0);
                ctx.lineTo(x * pixelSize, canvas.height);
                ctx.stroke();
            }
            for (let y = 0; y <= gridHeight; y++) {
                ctx.beginPath();
                ctx.moveTo(0, y * pixelSize);
                ctx.lineTo(canvas.width, y * pixelSize);
                ctx.stroke();
            }
        }
    }

    function updatePixel(canvasX, canvasY) {
        if (canvasX < 0 || canvasX >= canvas.width || canvasY < 0 || canvasY >= canvas.height) {
            return; // Clicked outside canvas bounds
        }
        const gridX = Math.floor(canvasX / pixelSize);
        const gridY = Math.floor(canvasY / pixelSize);

        if (gridX < 0 || gridX >= gridWidth || gridY < 0 || gridY >= gridHeight) {
            return; // Should not happen if initial check is correct, but good for safety
        }

        if (currentTool === 'pencil') {
            spriteData[gridY][gridX] = selectedColor;
        } else if (currentTool === 'eraser') {
            spriteData[gridY][gridX] = transparentColor;
        }
        drawGrid();
    }

    // --- Event Listeners ---

    let isDrawing = false;

    canvas.addEventListener('mousedown', (e) => {
        isDrawing = true;
        updatePixel(e.offsetX, e.offsetY);
    });

    canvas.addEventListener('mousemove', (e) => {
        if (isDrawing) {
            updatePixel(e.offsetX, e.offsetY);
        }
    });

    canvas.addEventListener('mouseup', () => {
        isDrawing = false;
    });

    canvas.addEventListener('mouseleave', () => {
        isDrawing = false; // Stop drawing if mouse leaves canvas
    });

    gridWidthInput.addEventListener('change', () => {
        gridWidth = parseInt(gridWidthInput.value);
        initializeSpriteData(); // Re-init data, existing drawing will be lost on resize
        resizeCanvas();
    });

    gridHeightInput.addEventListener('change', () => {
        gridHeight = parseInt(gridHeightInput.value);
        initializeSpriteData(); // Re-init data
        resizeCanvas();
    });

    pixelSizeInput.addEventListener('change', () => {
        pixelSize = parseInt(pixelSizeInput.value);
        resizeCanvas();
    });

    colorPicker.addEventListener('input', (e) => {
        selectedColor = e.target.value;
    });

    pencilToolButton.addEventListener('click', () => {
        currentTool = 'pencil';
        pencilToolButton.classList.add('active');
        eraserToolButton.classList.remove('active');
    });

    eraserToolButton.addEventListener('click', () => {
        currentTool = 'eraser';
        eraserToolButton.classList.add('active');
        pencilToolButton.classList.remove('active');
    });

    clearCanvasButton.addEventListener('click', () => {
        initializeSpriteData();
        drawGrid();
    });

    exportSpriteButton.addEventListener('click', () => {
        // Create a temporary canvas for export at native resolution
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = gridWidth;
        tempCanvas.height = gridHeight;
        const tempCtx = tempCanvas.getContext('2d');
        tempCtx.imageSmoothingEnabled = false; // Ensure crisp pixels

        for (let y = 0; y < gridHeight; y++) {
            for (let x = 0; x < gridWidth; x++) {
                tempCtx.fillStyle = spriteData[y][x];
                tempCtx.fillRect(x, y, 1, 1); // Draw 1x1 pixel
            }
        }

        const dataURL = tempCanvas.toDataURL('image/png');
        const link = document.createElement('a');
        link.href = dataURL;
        link.download = 'sprite.png';
        document.body.appendChild(link); // Required for Firefox
        link.click();
        document.body.removeChild(link);
    });

    // --- Initial Setup ---
    initializeSpriteData();
    resizeCanvas();
    pencilToolButton.classList.add('active'); // Default tool
});
```

**How to Use:**

